/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/card.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
import * as React from "react";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Card({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card" className={cn("flex flex-col gap-6 rounded-xl border bg-card py-6 text-card-foreground shadow-sm", className)} {...capconsSpread(props)} />;
}
function CardHeader({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-header" className={cn("@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-2 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6", className)} {...capconsSpread(props)} />;
}
function CardTitle({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-title" className={cn("leading-none font-semibold", className)} {...capconsSpread(props)} />;
}
function CardDescription({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-description" className={cn("text-sm text-muted-foreground", className)} {...capconsSpread(props)} />;
}
function CardAction({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-action" className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)} {...capconsSpread(props)} />;
}
function CardContent({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-content" className={cn("px-6", className)} {...capconsSpread(props)} />;
}
function CardFooter({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="card-footer" className={cn("flex items-center px-6 [.border-t]:pt-6", className)} {...capconsSpread(props)} />;
}
export { Card, CardHeader, CardFooter, CardTitle, CardAction, CardDescription, CardContent };
